// Source map reading, by hand (no dependency): the mappings' VLQ decoded, and the generated text
// grouped by the source module each segment maps to. Two builds are attributed by comparing those
// groups: a module is named when the text generated from it differs, or when one side lacks it.
import { posix } from 'node:path'

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const CONTINUATION = 32
const DIGIT = 31

/** Text generated by no source: a bundler's runtime, or a segment without a source field. */
export const UNMAPPED = '(unmapped)'

export interface SourceMap {
  readonly sources: readonly string[]
  readonly sourceRoot: string
  readonly mappings: string
}

/** The signed integers of one VLQ segment; throws on a character outside base64. */
export function decodeVlq(segment: string): number[] {
  const values: number[] = []
  let value = 0
  let shift = 0
  for (const char of segment) {
    const digit = BASE64.indexOf(char)
    if (digit < 0) throw new Error(`${JSON.stringify(char)} is not a base64 digit`)
    value += (digit & DIGIT) * 2 ** shift
    if ((digit & CONTINUATION) !== 0) {
      shift += 5
      continue
    }
    values.push(value % 2 === 1 ? -(value - 1) / 2 : value / 2)
    value = 0
    shift = 0
  }
  return values
}

/** One signed integer as VLQ: the inverse of `decodeVlq`, for tests and fixtures. */
export function encodeVlq(n: number): string {
  let value = n < 0 ? -n * 2 + 1 : n * 2
  let out = ''
  do {
    let digit = value & DIGIT
    value = Math.floor(value / 32)
    if (value > 0) digit |= CONTINUATION
    out += BASE64[digit]
  } while (value > 0)
  return out
}

/** A version 3 map with its sources and mappings, or undefined (an index map, or no map). */
export function parseSourceMap(text: string): SourceMap | undefined {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return undefined
  }
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return undefined
  const record = raw as Record<string, unknown>
  const sources = record['sources']
  const mappings = record['mappings']
  const sourceRoot = record['sourceRoot']
  if (record['version'] !== 3 || typeof mappings !== 'string' || !Array.isArray(sources)) return undefined
  if (!sources.every((source: unknown) => typeof source === 'string')) return undefined
  return { sources: sources as string[], mappings, sourceRoot: typeof sourceRoot === 'string' ? sourceRoot : '' }
}

/**
 * A source's path from the output root: resolved against the map's directory, unless it is a URL
 * or absolute. An absolute one (or its `file://` URL) under one of `roots`, the checkout the build
 * ran in, is named from that root, so a path that changes with each run never reaches the report.
 */
function sourcePath(source: string, sourceRoot: string, mapDir: string, roots: readonly string[]): string {
  const joined = sourceRoot === '' ? source : `${sourceRoot.replace(/\/+$/, '')}/${source}`
  const path = joined.startsWith('file://') ? joined.slice('file://'.length) : joined
  const root = roots.find(dir => path.startsWith(`${dir}/`))
  if (root !== undefined) return path.slice(root.length + 1)
  if (/^[a-z][a-z0-9+.-]*:/i.test(joined) || joined.startsWith('/')) return joined
  return posix.normalize(posix.join(mapDir, joined))
}

/**
 * The generated text grouped by source path, in first-seen order: each segment runs from its
 * column to the next segment's on the same line, text before a line's first segment is unmapped.
 * Columns count UTF-16 code units, as JavaScript strings do. Throws on a broken mapping.
 */
export function textBySource(generated: string, map: SourceMap, mapDir: string, roots: readonly string[] = []): Map<string, string> {
  const paths = map.sources.map(source => sourcePath(source, map.sourceRoot, mapDir, roots))
  const chunks = new Map<string, string[]>()
  const add = (key: string, text: string): void => {
    if (text === '') return
    const list = chunks.get(key) ?? []
    list.push(text)
    chunks.set(key, list)
  }
  const lines = generated.split('\n')
  const mapped = map.mappings.split(';')
  let source = 0
  for (let n = 0; n < lines.length; n++) {
    const line = lines[n] ?? ''
    let column = 0
    const starts: { column: number; source: number | undefined }[] = []
    for (const segment of (mapped[n] ?? '').split(',')) {
      if (segment === '') continue
      const [dc = 0, ds] = decodeVlq(segment)
      column += dc
      if (ds !== undefined) source += ds
      starts.push({ column, source: ds === undefined ? undefined : source })
    }
    add(UNMAPPED, line.slice(0, starts[0]?.column ?? line.length))
    starts.forEach((start, k) => {
      const path = start.source === undefined ? undefined : paths[start.source]
      add(path ?? UNMAPPED, line.slice(start.column, starts[k + 1]?.column ?? line.length))
    })
  }
  return new Map([...chunks].map(([key, list]) => [key, list.join('\n')]))
}

export interface Mapped {
  /** The generated text as the map indexes it: raw. */
  readonly text: string
  readonly map: SourceMap
  /** How a module's text is read before the sides are compared (hashed names without their hash); none, as it is. */
  readonly normalise?: (text: string) => string
}

/** The sources whose generated text differs between two sides, or that one side lacks, sorted. */
export function changedSources(base: Mapped, head: Mapped, mapDir: string, roots: readonly string[] = []): string[] {
  const read = (side: Mapped): Map<string, string> => {
    const chunks = textBySource(side.text, side.map, mapDir, roots)
    const normalise = side.normalise
    return normalise === undefined ? chunks : new Map([...chunks].map(([key, text]) => [key, normalise(text)]))
  }
  const before = read(base)
  const after = read(head)
  const keys = new Set([...before.keys(), ...after.keys()])
  return [...keys].filter(key => before.get(key) !== after.get(key)).sort()
}

/** The URL of the last `sourceMappingURL` comment of a JavaScript or CSS file, if any. */
export function mapUrlOf(text: string): string | undefined {
  const matches = [...text.matchAll(/[#@] sourceMappingURL=([^\s*]+)/g)]
  return matches.at(-1)?.[1]
}
